import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const s="/images/logic-studio/user-guide/blocks-a-en.png",u=JSON.parse('{"title":"Blocks A","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/logic-studio/user-guide/blocks-a.md","filePath":"en/projects/logic-studio/user-guide/blocks-a.md","lastUpdated":1794773886000}'),n={name:"en/projects/logic-studio/user-guide/blocks-a.md"};function i(c,e,h,l,d,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="blocks-a" tabindex="-1">Blocks A <a class="header-anchor" href="#blocks-a" aria-label="Permalink to &quot;Blocks A&quot;">​</a></h1><h2 id="first-example" tabindex="-1">First example <a class="header-anchor" href="#first-example" aria-label="Permalink to &quot;First example&quot;">​</a></h2><p>The example turns on a hallway light when the motion sensor changes to <code>on</code>.</p><ol><li>Choose <strong>New project → Blocks A</strong> and name the project. The workspace contains an <strong>Automation</strong> block.</li><li>Open <strong>Triggers</strong> and drag the state trigger into <strong>When</strong>. The screenshot uses <code>binary_sensor.flur_bewegung</code> and the state <code>on</code>. Select your own test helper or sensor.</li><li>Open <strong>Actions</strong> and drag a switch action into <strong>Then</strong>. The example uses <code>light.flur</code> and <strong>turn on</strong>. You can target a second test helper instead. Leave <strong>Only if</strong> empty for this example.</li><li>Click the flag icon to check the blocks. When the check passes, choose <strong>Open as HA YAML</strong> and review <code>triggers</code> and <code>actions</code> before exporting.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-a-en.png"><img src="'+s+'" alt="Blocks A with a state trigger in When and a switch action in Then"></a></p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="palette-and-connectors" tabindex="-1">Palette and connectors <a class="header-anchor" href="#palette-and-connectors" aria-label="Permalink to &quot;Palette and connectors&quot;">​</a></h3><p>Pick blocks by their role. Connector shapes indicate where a value or an action fits.</p><h3 id="triggers-and-conditions" tabindex="-1">Triggers and conditions <a class="header-anchor" href="#triggers-and-conditions" aria-label="Permalink to &quot;Triggers and conditions&quot;">​</a></h3><p>A trigger starts the automation. A condition can check whether the other helper is off.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><p>Stack actions in the order they should run.</p><h3 id="ha-selectors" tabindex="-1">HA selectors <a class="header-anchor" href="#ha-selectors" aria-label="Permalink to &quot;HA selectors&quot;">​</a></h3><p>Choose entities, actions, devices, areas, labels or floors. Check the corresponding ID in YAML.</p><h3 id="ha-yaml-draft" tabindex="-1">HA-YAML draft <a class="header-anchor" href="#ha-yaml-draft" aria-label="Permalink to &quot;HA-YAML draft&quot;">​</a></h3><p>Open the generated automation as a draft that identifies its source project.</p><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p>Check the YAML and use it in HA. Test the trigger and inspect the automation trace there.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>If a selector is empty, check the connected HA system for matching entries.</p>',20)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
